export const C={ink:'#111314',blue:'#1858f2',orange:'#f5a41e',paper:'#f7f5ef',white:'#ffffff',muted:'#6a7166',line:'#d9ded3',green:'#318655',red:'#a93f3f'};
const clamp=v=>Math.max(0,Math.min(1,v));
const ease=v=>{v=clamp(v);return 1-Math.pow(1-v,3);};
const phase=(p,start=0,end=.65)=>ease((p-start)/(end-start));
const lerp=(a,b,t)=>a+(b-a)*t;
function box(c,x,y,w,h,fill=C.white,r=12,stroke=C.line){c.beginPath();c.roundRect(x,y,w,h,r);c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=1.6;c.stroke();}}
function text(c,str,x,y,size=26,color=C.ink,align='center',weight=700){c.fillStyle=color;c.font=weight+' '+size+'px Plex,Arial,sans-serif';c.textAlign=align;c.direction='rtl';c.textBaseline='middle';c.fillText(String(str),x,y);}
function line(c,x1,y1,x2,y2,color=C.line,width=3){c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';c.stroke();}
function circle(c,x,y,r,fill=C.blue){c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fillStyle=fill;c.fill();}
function shadow(c,x,y,w,alpha=.12){c.save();c.globalAlpha=alpha;c.fillStyle=C.ink;c.beginPath();c.ellipse(x,y,w,10,0,0,Math.PI*2);c.fill();c.restore();}
function check(c,x,y,s=25,p=1,color=C.green){c.save();c.translate(x,y);c.beginPath();c.moveTo(-s*.5,0);if(p<.4)c.lineTo(lerp(-s*.5,-s*.1,p/.4),lerp(0,s*.4,p/.4));else {c.lineTo(-s*.1,s*.4);c.lineTo(lerp(-s*.1,s*.6,(p-.4)/.6),lerp(s*.4,-s*.45,(p-.4)/.6));}c.strokeStyle=color;c.lineWidth=5;c.lineCap='round';c.lineJoin='round';c.stroke();c.restore();}
function cross(c,x,y,s=15,color=C.red){line(c,x-s,y-s,x+s,y+s,color,4);line(c,x+s,y-s,x-s,y+s,color,4);}
function cursor(c,x,y,pressed=false){c.save();c.translate(x,y);if(pressed)c.scale(.86,.86);c.beginPath();c.moveTo(0,0);c.lineTo(0,37);c.lineTo(10,28);c.lineTo(17,44);c.lineTo(25,40);c.lineTo(18,24);c.lineTo(32,23);c.closePath();c.fillStyle=C.ink;c.fill();c.strokeStyle=C.white;c.lineWidth=2;c.stroke();c.restore();}
function product(c,x,y,s=1,color=C.blue){c.save();c.translate(x,y);c.scale(s,s);shadow(c,0,83,60);box(c,-54,-68,108,142,color,10,C.ink);box(c,-42,-81,84,20,C.ink,6,null);box(c,-36,-31,72,70,C.paper,5,null);line(c,-20,-15,20,-15,C.ink,3);text(c,'منتج',0,8,19,C.ink);line(c,-16,27,16,27,C.orange,4);c.restore();}
function parcel(c,x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);box(c,-37,-29,74,59,C.orange,5,C.ink);line(c,0,-29,0,30,C.ink,2);box(c,-12,-29,24,15,'#ffcd70',1,null);box(c,12,2,16,10,C.paper,1,null);c.restore();}
function money(c,x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);box(c,-28,-17,56,34,'#b9dbc5',4,C.green);circle(c,0,0,9,C.green);line(c,-22,0,-18,0,C.green,2);line(c,18,0,22,0,C.green,2);c.restore();}
function card(c,x,y,w=160,h=110,label='طلب',value=null,color=C.white){box(c,x-w/2,y-h/2,w,h,color);text(c,label,x,y-(value===null?0:20),21);if(value!==null)text(c,value,x,y+20,28,C.blue);}
function arrow(c,x1,y1,x2,y2,p=1,color=C.blue){const x=lerp(x1,x2,p),y=lerp(y1,y2,p);line(c,x1,y1,x,y,color,3);if(p>.9){const a=Math.atan2(y2-y1,x2-x1);line(c,x,y,x-11*Math.cos(a-.5),y-11*Math.sin(a-.5),color,3);line(c,x,y,x-11*Math.cos(a+.5),y-11*Math.sin(a+.5),color,3);}}
